package dev.labflow.eval;
import static org.junit.jupiter.api.Assertions.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
class TeamStatisticsTest {
  final ObjectMapper json=new ObjectMapper();
  @Test void bootstrapHasKnownBernoulliBoundsAndAReproducibleSeed(){var interval=TeamBootstrap.interval(json,new double[]{0,1},18010);assertEquals(.5,interval.path("mean").asDouble());assertEquals(0,interval.path("lower_95").asDouble());assertEquals(1,interval.path("upper_95").asDouble());assertEquals(interval,TeamBootstrap.interval(json,new double[]{0,1},18010));}
  @Test void bootstrapHandlesConstantAndAbsentPairsWithoutFabricatingConfidence(){var constant=TeamBootstrap.interval(json,new double[]{2,2,2},18010);assertEquals(2,constant.path("lower_95").asDouble());assertEquals(2,constant.path("upper_95").asDouble());assertTrue(TeamBootstrap.interval(json,new double[0],18010).path("mean").isNull());assertThrows(IllegalArgumentException.class,()->TeamBootstrap.interval(json,new double[]{Double.NaN},18010));}
  @Test void liveComparisonMustReserveBothHalvesAndRetainUnknownSpend(){var enough=new EvaluationSpendBudget(".96","8");assertTrue(enough.canStartPair());var insufficient=new EvaluationSpendBudget(".95","8");assertTrue(insufficient.canStartCase());assertFalse(insufficient.canStartPair());enough.record(json.createObjectNode().put("usage_complete",false).put("tokens",0));assertTrue(enough.canStartCase());assertFalse(enough.canStartPair());enough.record(json.createObjectNode().put("usage_complete",false).put("tokens",0));assertFalse(enough.canStartCase());assertEquals(.96,enough.report(json,0).path("estimated_cny").asDouble(),1e-12);}
  @Test void explicitUnlimitedCostStillAccountsForReportedAndUnknownUsage(){var budget=EvaluationSpendBudget.unlimited("8");budget.record(json.createObjectNode().put("usage_complete",true).put("tokens",1_000_000));budget.record(json.createObjectNode().put("usage_complete",false).put("tokens",0));assertTrue(budget.canStartCase());assertTrue(budget.canStartPair());var report=budget.report(json,0);assertTrue(report.path("ceiling_cny").isNull());assertFalse(report.path("cost_limit_enabled").asBoolean());assertEquals(1_000_000,report.path("spent_tokens").asLong());assertEquals(1_060_000,report.path("reserved_or_reported_tokens").asLong());assertEquals(1,report.path("unknown_usage_cases").asInt());assertEquals(8.48,report.path("estimated_cny").asDouble(),1e-12);assertThrows(IllegalArgumentException.class,()->EvaluationSpendBudget.unlimited("0"));}
  @Test void unlimitedConfigurationIsExplicitAndDoesNotChangeTheBoundedDefault(){String prior=System.getProperty("labflow.eval.unlimitedCost");try{System.setProperty("labflow.eval.unlimitedCost","true");assertTrue(EvaluationSpendBudget.configured().report(json,0).path("ceiling_cny").isNull());System.setProperty("labflow.eval.unlimitedCost","false");assertTrue(EvaluationSpendBudget.configured().report(json,0).path("cost_limit_enabled").asBoolean());}finally{if(prior==null)System.clearProperty("labflow.eval.unlimitedCost");else System.setProperty("labflow.eval.unlimitedCost",prior);}}
  @Test void unrestrictedUnknownUsageHasNoInventedFiniteCostEstimate(){String prior=System.getProperty("labflow.team.unbounded");try{System.setProperty("labflow.team.unbounded","true");var budget=EvaluationSpendBudget.unlimited("8");budget.record(json.createObjectNode().put("tokens",0).put("usage_complete",false));assertTrue(budget.report(json,0).path("estimated_cny").isNull());assertTrue(budget.report(json,0).path("estimate_incomplete").asBoolean());assertTrue(budget.canStartPair());}finally{if(prior==null)System.clearProperty("labflow.team.unbounded");else System.setProperty("labflow.team.unbounded",prior);}}
}
